#define BATCH_PRUNING_NO_MAIN
#include "batch_pruning.cpp"
#undef BATCH_PRUNING_NO_MAIN

struct WQuery{const float*q=nullptr;float tau=0;std::vector<uint8_t>selected;};
struct Segment{int node=-1;bool batch=false;};
struct DPResult{double raw=0,best=0;std::vector<Segment>segments;};

static DPResult learn_node(const BTree&t,int u,const SQ4&sq,const std::vector<WQuery>&work,int cluster,int max_block){const BNode&n=t.nodes[u];DPResult z;if(n.leaf()){for(const WQuery&w:work)if(w.selected[cluster])z.raw+=72+512*(sq.lb(w.q,t.ids[n.begin])<=w.tau);z.best=z.raw;z.segments={{u,false}};}else{DPResult l=learn_node(t,n.left,sq,work,cluster,max_block),r=learn_node(t,n.right,sq,work,cluster,max_block);z.raw=l.raw+r.raw;z.best=l.best+r.best;z.segments=std::move(l.segments);z.segments.insert(z.segments.end(),r.segments.begin(),r.segments.end());}
 int count=n.end-n.begin;if(count<=max_block){double block=0;for(const WQuery&w:work)if(w.selected[cluster]){block+=108;if(qcenter_lb(w.q,n,sq)<=w.tau){block+=72.0*count;for(int p=n.begin;p<n.end;++p)block+=512*(sq.lb(w.q,t.ids[p])<=w.tau);}}if(block<z.best){z.best=block;z.segments={{u,true}};}}
 if(z.raw<z.best){z.best=z.raw;z.segments={{u,false}};}return z;}

struct Eval{double bytes=0;uint64_t blocks=0,raw_objects=0,pruned=0,opened=0,exact=0;};
static Eval evaluate(const BTree&t,const std::vector<Segment>&plan,const SQ4&sq,const float*q,float tau){Eval e;for(const Segment&s:plan){const BNode&n=t.nodes[s.node];int count=n.end-n.begin;if(!s.batch){e.raw_objects+=count;e.opened+=count;e.bytes+=72.0*count;for(int p=n.begin;p<n.end;++p)if(sq.lb(q,t.ids[p])<=tau){++e.exact;e.bytes+=512;}}else{++e.blocks;e.bytes+=108;if(qcenter_lb(q,n,sq)>tau)e.pruned+=count;else{e.opened+=count;e.bytes+=72.0*count;for(int p=n.begin;p<n.end;++p)if(sq.lb(q,t.ids[p])<=tau){++e.exact;e.bytes+=512;}}}}return e;}

struct QCfg{std::string data="../dataset/sift",assign="../populated_index/PriorMax_SIFT1M_C100_clusterid.tsv",out="query_aware_batch_results.csv";int base=100000,test_n=50,train_n=50,k=100,max_block=16;std::vector<int>probes{8,16,32,64,100};};
static QCfg qparse(int ac,char**av){QCfg c;for(int i=1;i<ac;++i){std::string a=av[i];auto v=[&](){if(++i==ac)throw std::runtime_error("missing value");return std::string(av[i]);};if(a=="--dataset")c.data=v();else if(a=="--assignments")c.assign=v();else if(a=="--output")c.out=v();else if(a=="--base")c.base=std::stoi(v());else if(a=="--test-queries")c.test_n=std::stoi(v());else if(a=="--train-queries")c.train_n=std::stoi(v());else if(a=="--k")c.k=std::stoi(v());else if(a=="--max-block")c.max_block=std::stoi(v());else if(a=="--nprobes")c.probes=bints(v());else throw std::runtime_error("unknown option "+a);}return c;}

static std::vector<WQuery> make_work(const Matrix&xb,const Matrix&xq,int begin,int count,int np,int k,const std::vector<std::vector<int>>&ls,const std::vector<std::vector<float>>&cs,const SQ4*sq,double*flat_bytes=nullptr){std::vector<WQuery>out;for(int ii=0;ii<count;++ii){int qi=begin+ii;WQuery w;w.q=xq[qi];w.selected.assign(100,0);std::vector<int>pr(100);std::iota(pr.begin(),pr.end(),0);std::partial_sort(pr.begin(),pr.begin()+np,pr.end(),[&](int a,int b){float x=l2(w.q,cs[a].data(),xb.d),y=l2(w.q,cs[b].data(),xb.d);return x<y||(x==y&&a<b);});std::priority_queue<std::pair<float,int>>top;for(int z=0;z<np;++z){int c=pr[z];w.selected[c]=1;for(int id:ls[c]){float d=l2(w.q,xb[id],xb.d);if((int)top.size()<k)top.push({d,id});else if(d<top.top().first){top.pop();top.push({d,id});}}}w.tau=std::sqrt(top.top().first);if(flat_bytes&&sq)for(int c=0;c<100;++c)if(w.selected[c])for(int id:ls[c]){*flat_bytes+=72;if(sq->lb(w.q,id)<=w.tau)*flat_bytes+=512;}out.push_back(std::move(w));}return out;}

int main(int ac,char**av)try{QCfg cfg=qparse(ac,av);Matrix xb=fvecs(cfg.data+"/sift_base.fvecs",cfg.base),xq=fvecs(cfg.data+"/sift_query.fvecs",cfg.test_n+cfg.train_n);auto ls=prefix_lists(cfg.assign,xb.rows());auto cs=centers(xb,ls);SQ4 sq(xb);std::cerr<<"Building singleton candidate trees...\n";BatchForest forest(xb,sq,ls,1);std::ofstream out(cfg.out);out<<"base,k,nprobe,max_block,train_queries,test_queries,train_flat_bytes,train_learned_bytes,train_reduction,test_flat_bytes,test_learned_bytes,test_reduction,avg_batch_segments,avg_raw_objects,test_prune_ratio,test_exact_open\n";std::cout<<"nprobe train_reduction test_reduction batches raw_objects prune\n";
for(int np:cfg.probes){double train_flat=0,test_flat=0;auto train=make_work(xb,xq,cfg.test_n,cfg.train_n,np,cfg.k,ls,cs,&sq,&train_flat);auto test=make_work(xb,xq,0,cfg.test_n,np,cfg.k,ls,cs,&sq,&test_flat);std::vector<std::vector<Segment>>plans(100);double train_best=0;for(int c=0;c<100;++c)if(!forest.trees[c].nodes.empty()){DPResult d=learn_node(forest.trees[c],0,sq,train,c,cfg.max_block);plans[c]=std::move(d.segments);train_best+=d.best;}
 double test_bytes=0;uint64_t blocks=0,raw=0,pruned=0,opened=0,exact=0,selected_points=0;for(const WQuery&w:test)for(int c=0;c<100;++c)if(w.selected[c]){Eval e=evaluate(forest.trees[c],plans[c],sq,w.q,w.tau);test_bytes+=e.bytes;blocks+=e.blocks;raw+=e.raw_objects;pruned+=e.pruned;opened+=e.opened;exact+=e.exact;selected_points+=forest.trees[c].ids.size();}double tr=1-train_best/train_flat,te=1-test_bytes/test_flat;out<<xb.rows()<<','<<cfg.k<<','<<np<<','<<cfg.max_block<<','<<cfg.train_n<<','<<cfg.test_n<<','<<train_flat/cfg.train_n<<','<<train_best/cfg.train_n<<','<<tr<<','<<test_flat/cfg.test_n<<','<<test_bytes/cfg.test_n<<','<<te<<','<<blocks/(double)cfg.test_n<<','<<raw/(double)cfg.test_n<<','<<pruned/(double)selected_points<<','<<exact/(double)cfg.test_n<<'\n';std::cout<<std::setw(6)<<np<<' '<<std::fixed<<std::setprecision(4)<<tr<<' '<<te<<' '<<std::setprecision(1)<<blocks/(double)cfg.test_n<<' '<<raw/(double)cfg.test_n<<' '<<std::setprecision(4)<<pruned/(double)selected_points<<'\n';}
std::cerr<<"Wrote "<<cfg.out<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
